 * @example
 * ```typescript
 * const { shouldHide, isLoading, isReady, isAuthenticated } = useAuthVisibility();
 *
 * if (shouldHide) return null;
 *
 * if (isLoading) {
 *   return <Button disabled><Spinner /></Button>;
 * }
 *
 * if (isAuthenticated) {
 *   return <UserMenu />;
 * }
 *
 * return <SignInButton />;
 * ```
